 const parity=JSON.parse(read(folder+'all-forms-checks.json'));assert.equal(parity.forms,60);assert.equal(parity.checks.length,482);assert.deepEqual(parity.errors,[]);const desktop=JSON.parse(read(folder+'desktop-preservation.json'));assert.equal(desktop.checks.length,4);for(const c of desktop.checks)assert(c.desktopLayoutTypographyColorsEqualLive);const closed=JSON.parse(read(folder+'paper-closed-checks.json'));assert.equal(closed.checks.length,48);assert.deepEqual(closed.errors,[]);for(const c of closed.checks)assert(c.allControlsFullyVisible&&c.touchTargets44&&c.stageFits&&c.outerFits);
